});

test('invoiceTotals sums a single line', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 14280);
  assert.equal(totals.total, 82280);
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
      { qty: 2, unitPrice: 980, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68000 + 1960 + 120000);
  const vat = 14280 + 411 + 25200;
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 189960 + vat);
});

test('invoiceTotals returns new object', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000 }],
  };

  const totals1 = invoiceTotals(invoice);
