    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  const invoice = result.value;
  const originalLinesCopy = JSON.parse(JSON.stringify(invoice.lines));

  removeLine(invoice, 'ICON-SET');

  assert.deepEqual(invoice.lines, originalLinesCopy);
});

test('removeLine preserves other invoice properties', () => {
  const result = createInvoice({
    customerId: 'C-005',
    issueDate: '2023-12-25',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  const invoice = result.value;
  const removeResult = removeLine(invoice, 'ICON-SET');

  assert.equal(removeResult.value.customerId, 'C-005');
  assert.equal(removeResult.value.issueDate, '2023-12-25');
  assert.equal(removeResult.value.status, 'draft');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const issueResult = issueInvoice(invoice, []);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2024-0001');
  assert.equal(issueResult.value.status, 'issued');
  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2024-10-15');
});

test('issueInvoice uses existing numbers to generate next number', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002', 'INV-2024-0003'];
  const issueResult = issueInvoice(invoice, existingNumbers);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2024-0004');
});

test('issueInvoice returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'issued',
    number: 'INV-2024-0001',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('issueInvoice preserves all line data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
