    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 8, discountPercent: -5 }],
    }).error,
    'DISCOUNT_INVALID',
  );

  assert.equal(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 8, discountPercent: 105 }],
    }).error,
    'DISCOUNT_INVALID',
  );

  assert.equal(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 8, discountPercent: 'abc' }],
    }).error,
    'DISCOUNT_INVALID',
  );
});

test('lineDiscount calculates discount amount', () => {
