      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'INVALID-SKU', qty: 1 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice works with single line', () => {
  const result = createInvoice({
    customerId: 'C-005',
    issueDate: '2023-12-25',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-005');
  assert.equal(result.value.issueDate, '2023-12-25');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].name, 'Brand workshop (day, VAT exempt)');
  assert.equal(result.value.lines[0].vatRate, 0);
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 3 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines,
  });

  assert.deepEqual(lines, linesCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1000 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 980 }), 9800);
});

test('lineTotal handles small unit prices', () => {
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 37 }), 74);
});

test('lineTotal handles large quantities and prices', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 120000 }), 120000000);
});

test('invoiceTotals sums a single line', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 14280);
  assert.equal(totals.total, 82280);
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
      { qty: 2, unitPrice: 980, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 68000 + 1960 + 120000);
  const vat = 14280 + 412 + 25200;
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 189960 + vat);
});

test('invoiceTotals returns new object', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000 }],
  };

  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);

  assert.notStrictEqual(totals1, totals2);
});

test('invoiceTotals with enriched invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 8 * 8500 + 2 * 980);
  assert.equal(totals.discount, 3500);
  assert.equal(totals.vat, 13958);
  assert.equal(totals.total, 80418);
});

test('addLine adds a new SKU to the invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'ICON-SET', qty: 5 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 2);
  assert.deepEqual(addResult.value.lines[1], {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 5,
    unitPrice: 980,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].qty, 11);
});

test('addLine returns QTY_INVALID for bad qty', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  assert.equal(addLine(invoice, { sku: 'ICON-SET', qty: 0 }).error, 'QTY_INVALID');
  assert.equal(addLine(invoice, { sku: 'ICON-SET', qty: -5 }).error, 'QTY_INVALID');
  assert.equal(addLine(invoice, { sku: 'ICON-SET', qty: 2.5 }).error, 'QTY_INVALID');
});

test('addLine returns UNKNOWN_SKU for invalid SKU', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'INVALID-SKU', qty: 1 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('addLine returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 8, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 1 });
