test('removeLine preserves other invoice properties', () => {
  const result = createInvoice({
    customerId: 'C-005',
    issueDate: '2023-12-25',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 2 },
    ],
