  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2024-10-15');
});

test('issueInvoice uses existing numbers to generate next number', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;

  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002', 'INV-2024-0003'];
